'use client';
import {useEffect,useMemo,useState} from 'react';
const sections=[['◇','تعريف المواد','products','gold'],['◆','إضافة البراندات','brands','teal'],['♙','إضافة الزبائن','customers','blue'],['▤','بيع جملة','sale','blue'],['↓','تسديد جملة','customerPayment','teal'],['☀','بيع منظومات','system','gold'],['☀↓','تسديد منظومات','systemPayment','gold'],['⌂','إضافة الموردين','suppliers','violet'],['≡','كشف حساب عميل','customerStatement','blue'],['≡','كشف حساب مورد','supplierStatement','violet'],['🛒','فاتورة شراء','purchase','violet'],['▦','المخزون','stock','teal'],['▥','الصندوق','cash','blue'],['↗','الأرباح','profit','teal'],['↻','تحديثات البرنامج','updates','violet']];
const load=(k,d)=>{if(typeof window==='undefined')return d;try{return JSON.parse(localStorage.getItem(k))||d}catch{return d}};
const a4=(title,body,total='',subtitle='')=>'<!doctype html><html dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>@page{size:A4 portrait;margin:10mm}*{box-sizing:border-box}html,body{margin:0;padding:0;background:#fff;color:#17364b;font-family:Tahoma,Arial,sans-serif;font-size:12px}.sheet{width:190mm;max-width:100%;min-height:277mm;margin:0 auto;padding:7mm}.head{display:grid;grid-template-columns:1fr auto;gap:10mm;align-items:center;border-bottom:2px solid #0b8f82;padding-bottom:4mm;margin-bottom:5mm}.brand{display:flex;align-items:center;gap:3mm}.logo{width:14mm;height:14mm;border-radius:4mm;background:#0b8f82;color:#fff;display:grid;place-items:center;font-size:22px;flex:none}.brand h1{font-size:20px;margin:0}.brand p{margin:1mm 0 0;color:#71838d;font-size:11px}.doc{text-align:left;max-width:60mm}.doc h2{margin:0;font-size:18px;line-height:1.4}.doc small{color:#71838d}.meta{display:grid;grid-template-columns:1fr 1fr;gap:3mm;margin:4mm 0}.meta div{background:#f3f8fa;border:1px solid #dce8ec;border-radius:2mm;padding:3mm;line-height:1.5}table{width:100%;border-collapse:collapse;table-layout:fixed;margin-top:4mm}th{background:#174d67;color:#fff;padding:3mm 2mm;text-align:center;font-size:11px;white-space:normal}td{padding:3mm 2mm;border-bottom:1px solid #dce6ea;text-align:center;vertical-align:middle;overflow-wrap:anywhere}tr:nth-child(even) td{background:#f7fafb}.total{margin-top:5mm;background:#174d67;color:#fff;padding:4mm;border-radius:3mm;display:flex;justify-content:space-between;align-items:center;font-size:16px;font-weight:bold}.notes{margin-top:4mm;border:1px solid #dce6ea;border-radius:2mm;padding:3mm;min-height:14mm;line-height:1.6}.foot{margin-top:8mm;padding-top:3mm;border-top:1px solid #dce6ea;color:#78909b;font-size:9px;text-align:center}.actions{position:fixed;bottom:12px;left:12px}.actions button{border:0;border-radius:9px;padding:11px 15px;background:#0b8f82;color:#fff;font-weight:bold}@media(max-width:700px){html,body{font-size:11px}.sheet{width:100%;min-height:0;padding:12px}.head{gap:10px}.brand h1{font-size:17px}.doc{max-width:42%}.doc h2{font-size:15px}.logo{width:44px;height:44px}.meta{grid-template-columns:1fr 1fr;gap:7px}th,td{padding:9px 5px;font-size:10px}.total{font-size:14px}.actions{position:static;margin:18px 12px}.actions button{width:100%}}@media print{html,body{font-size:11px}.sheet{width:190mm;max-width:none;min-height:auto;padding:0}.actions{display:none}th,td{font-size:10px;padding:2.5mm 1.5mm}.head{break-inside:avoid}.total{break-inside:avoid}}</style></head><body><div class="sheet"><div class="head"><div class="brand"><div class="logo">☀</div><div><h1>عبدالرحمن سولار</h1><p>طاقة شمسية</p></div></div><div class="doc"><h2>'+title+'</h2><small>'+subtitle+'</small></div></div>'+body+(total?'<div class="total"><span>الإجمالي / الرصيد</span><b>'+total+'</b></div>':'')+'<div class="foot">عبدالرحمن سولار • مستند صادر من النظام</div></div><div class="actions"><button onclick="window.print()">حفظ PDF / طباعة A4</button></div></body></html>';
const fmt=n=>n===''?'':Number(n||0).toLocaleString('en-US',{maximumFractionDigits:2});
const openA4=(html)=>{const w=window.open('','_blank');if(!w)return alert('اسمح بالنوافذ المنبثقة');w.document.write(html);w.document.close()};
const saveA4=(html,name)=>{const b=new Blob([html],{type:'text/html;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
const shareA4=async(title,text,html)=>{if(navigator.share){try{const file=new File([html],title+'.html',{type:'text/html'});if(navigator.canShare&&navigator.canShare({files:[file]}))return await navigator.share({title,files:[file]});await navigator.share({title,text})}catch(e){if(e.name!=='AbortError')await navigator.clipboard.writeText(text)}}else{await navigator.clipboard.writeText(text);alert('تم نسخ الكشف للمشاركة')}};

export default function Home(){
 const [page,setPage]=useState('home'); const [products,setProducts]=useState([]); const [brands,setBrands]=useState([]); const [customers,setCustomers]=useState([]); const [suppliers,setSuppliers]=useState([]); const [tx,setTx]=useState([]); const [invoiceItems,setInvoiceItems]=useState([]); const [search,setSearch]=useState('');
 useEffect(()=>{setProducts(load('solar_products',[]));setBrands(load('solar_brands',[]));setCustomers(load('solar_customers',[]));setSuppliers(load('solar_suppliers',[]));setTx(load('solar_tx',[]))},[]);
 const save=(k,v,set)=>{set(v);localStorage.setItem(k,JSON.stringify(v))};
 const cash=useMemo(()=>tx.reduce((a,t)=>{if(t.cash){const out=t.kind==='purchase'||t.kind==='supplier_payment'||t.kind==='cash_expense';a.IQD+=(out?-1:1)*Number(t.total||0)}return a},{IQD:0}),[tx]);
 const stockValue=products.reduce((s,p)=>s+(+p.qty||0)*(+p.cost||0),0);
 const addMaster=(type,e)=>{e.preventDefault();const f=new FormData(e.currentTarget);const row={id:Date.now(),name:f.get('name'),phone:f.get('phone')||'',customerType:f.get('customerType')||''};if(type==='customers')save('solar_customers',[...customers,row],setCustomers);else save('solar_suppliers',[...suppliers,row],setSuppliers);e.currentTarget.reset()};
 const addProduct=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const next=products.reduce((m,p)=>Math.max(m,parseInt(String(p.code||'').replace(/\D/g,''))||0),0)+1;const row={id:Date.now(),code:String(next).padStart(4,'0'),name:f.get('name'),brand:f.get('brand')||'',category:f.get('category')||'',cost:'',qty:0};save('solar_products',[...products,row],setProducts);e.currentTarget.reset()};
 const transact=(kind,e)=>{e.preventDefault();const f=new FormData(e.currentTarget),pid=+f.get('product'),qty=+f.get('qty'),price=+f.get('price'),currency=f.get('currency'),cashMode=f.get('mode')==='cash';const p=products.find(x=>x.id===pid);if(!p)return alert('اختر مادة');if((kind==='sale'||kind==='system')&&p.qty<qty)return alert('الكمية غير كافية');const updated=products.map(x=>x.id===pid?{...x,qty:x.qty+(kind==='purchase'?qty:-qty),cost:kind==='purchase'?price:x.cost}:x);save('solar_products',updated,setProducts);const row={id:Date.now(),kind,product:p.name,qty,price,total:qty*price,currency,cash:cashMode,date:new Date().toISOString(),party:f.get('party')||'',cost:p.cost};save('solar_tx',[...tx,row],setTx);e.currentTarget.reset();alert('تم الحفظ')};
 const deleteInvoice=(inv)=>{if(!confirm('حذف الفاتورة نهائياً وإلغاء تأثيرها على المخزون والحسابات؟'))return;let updated=[...products];(inv.items||[]).forEach(it=>{updated=updated.map(p=>p.id===it.id?{...p,qty:(+p.qty||0)+(inv.kind==='sale'?(+it.qty||0):-(+it.qty||0))}:p)});save('solar_products',updated,setProducts);save('solar_tx',tx.filter(t=>t.id!==inv.id),setTx);alert('تم حذف الفاتورة وإلغاء تأثيرها')};
 const updateInvoice=(oldInv,newInv)=>{let updated=[...products];(oldInv.items||[]).forEach(it=>{updated=updated.map(p=>p.id===it.id?{...p,qty:(+p.qty||0)+(oldInv.kind==='sale'?(+it.qty||0):-(+it.qty||0))}:p)});(newInv.items||[]).forEach(it=>{updated=updated.map(p=>p.id===it.id?{...p,qty:(+p.qty||0)+(oldInv.kind==='purchase'?(+it.qty||0):-(+it.qty||0)),cost:oldInv.kind==='purchase'?(+it.price||p.cost):p.cost}:p)});save('solar_products',updated,setProducts);save('solar_tx',tx.map(t=>t.id===oldInv.id?{...oldInv,...newInv,id:oldInv.id,date:oldInv.date}:t),setTx);alert('تم تعديل الفاتورة والحسابات')};
 const title={products:'تعريف المواد',brands:'إضافة البراندات',customers:'إضافة الزبائن',customerPayment:'تسديد جملة',systemPayment:'تسديد منظومات',suppliers:'إضافة الموردين',customerStatement:'كشف حساب عميل',supplierStatement:'كشف حساب مورد',purchase:'شراء',sale:'بيع جملة',system:'بيع منظومات',stock:'المخزن',cash:'الصندوق',profit:'الأرباح',updates:'تحديثات البرنامج'}[page];
 if(page!=='home')return <main><div className="top"><button onClick={()=>setPage('home')}>← الرئيسية</button><h2>{title}</h2></div>{page==='products'&&<ProductsManager brands={brands} products={products} setProducts={v=>save('solar_products',v,setProducts)} addProduct={addProduct}/>} {page==='brands'&&<BrandsManager brands={brands} setBrands={v=>save('solar_brands',v,setBrands)}/>} {page==='customers'&&<><PartyManager customer rows={customers} setRows={v=>save('solar_customers',v,setCustomers)} tx={tx} onAdd={e=>addMaster('customers',e)} onPayment={(r,a,note)=>save('solar_tx',[...tx,{id:Date.now(),kind:'customer_payment',party:r.name,total:+a,currency:'IQD',cash:true,notes:note||'',date:new Date().toISOString()}],setTx)}/><CustomerDebts customers={customers} tx={tx}/></>} {page==='suppliers'&&<PartyManager rows={suppliers} setRows={v=>save('solar_suppliers',v,setSuppliers)} tx={tx} onAdd={e=>addMaster('suppliers',e)} onPayment={(r,a,note)=>save('solar_tx',[...tx,{id:Date.now(),kind:'supplier_payment',party:r.name,total:+a,currency:'IQD',cash:true,notes:note||'',date:new Date().toISOString()}],setTx)}/>} {page==='customerPayment'&&<CustomerPayment customers={customers} tx={tx} onSave={(row)=>save('solar_tx',[...tx,row],setTx)}/>} {page==='systemPayment'&&<SystemPayment customers={customers} tx={tx} onSave={(row)=>save('solar_tx',[...tx,row],setTx)}/>} {page==='customerStatement'&&<StatementPage customer parties={customers} tx={tx}/>} {page==='supplierStatement'&&<StatementPage parties={suppliers} tx={tx}/>} {(page==='sale'||page==='purchase')&&<InvoiceBuilder history={tx.filter(t=>t.kind===page)} onDeleteInvoice={deleteInvoice} onUpdateInvoice={updateInvoice} kind={page} products={products} parties={page==='purchase'?suppliers:customers.filter(c=>String(c.customerType||'').includes('جملة'))} items={invoiceItems} setItems={setInvoiceItems} search={search} setSearch={setSearch} onSave={(meta)=>{if(!invoiceItems.length)return alert('أضف مادة'); let updated=[...products]; const subtotal=invoiceItems.reduce((a,x)=>a+(+x.qty||0)*(+x.price||0),0), expenses=(+meta.expenses||0); invoiceItems.forEach(it=>{const line=(+it.qty||0)*(+it.price||0),allocated=subtotal>0?expenses*(line/subtotal):0,landed=(+it.qty||0)>0?(line+allocated)/(+it.qty||0):(+it.price||0);updated=updated.map(p=>p.id===it.id?{...p,qty:(+p.qty||0)+(page==='purchase'?(+it.qty||0):-(+it.qty||0)),cost:page==='purchase'?landed:p.cost}:p)}); save('solar_products',updated,setProducts); const total=subtotal; save('solar_tx',[...tx,{id:Date.now(),kind:page,items:invoiceItems.map(it=>({...it,landedCost:page==='purchase'?((+it.qty||0)>0?(((+it.qty||0)*(+it.price||0)+(subtotal>0?expenses*(((+it.qty||0)*(+it.price||0))/subtotal):0))/(+it.qty||0)):(+it.price||0)):undefined})),total:total+expenses,subtotal:total,expenses,currency:'IQD',cash:meta.mode==='cash',party:meta.party,notes:meta.notes,date:new Date().toISOString()}],setTx); setInvoiceItems([]); alert('تم حفظ الفاتورة');}}/>} {page==='system'&&<SystemSale products={products} customers={customers.filter(c=>String(c.customerType||'').includes('مفرد'))} onSave={(data)=>{let updated=[...products];data.items.forEach(it=>{updated=updated.map(p=>p.id===it.id?{...p,qty:p.qty-it.qty}:p)});save('solar_products',updated,setProducts);save('solar_tx',[...tx,{...data,id:Date.now(),kind:'system',date:new Date().toISOString()}],setTx);}}/>} {page==='stock'&&<StockReport products={products}/>} {page==='cash'&&<CashBox tx={tx} balance={cash.IQD} onAdd={(kind,amount,note)=>save('solar_tx',[...tx,{id:Date.now(),kind,total:+amount,currency:'IQD',cash:true,notes:note||'',date:new Date().toISOString()}],setTx)}/>}  {page==='profit'&&<Profit tx={tx}/>} {page==='updates'&&<div className="updateBox"><b>طاقة شمسية V2</b><span>واجهة رئيسية أوضح للموبايل ونظام تحديث تلقائي.</span><em>النظام محدث ✓</em></div>} {(page==='payments'||page==='statements')&&<div className="empty">هذا القسم جاهز للمرحلة التالية بعد ربط قاعدة البيانات.</div>}</main>;
 return <main className="home"><div className="brand"><div className="brandIcon">☀</div><div><h1>طاقة شمسية</h1><p>عبدالرحمن كروب</p></div></div><div className="miniStats one"><div><small>الصندوق</small><b>{cash.IQD.toLocaleString()} د.ع</b></div></div><h2 className="homeTitle">الرئيسية</h2><section className="menuGrid">{sections.map(([i,t,k,color])=><button key={k} onClick={()=>setPage(k)} className={color}><span className="menuIcon">{i}</span><b>{t}</b></button>)}</section><div className="version">V2 • تحديث تلقائي</div></main>
}
function Master({onSubmit,rows}){return <><form onSubmit={onSubmit} className="card form"><input name="name" placeholder="الاسم" required/><input name="phone" placeholder="رقم الهاتف"/><button>حفظ</button></form><List rows={rows.map(x=>[x.name,x.phone])}/></>}
function TxForm({kind,products,parties,onSubmit}){return <form onSubmit={onSubmit} className="card form"><select name="party"><option value="">{kind==='purchase'?'اختر المورد':'اختر العميل'}</option>{parties.map(x=><option key={x.id}>{x.name}</option>)}</select><select name="product" required><option value="">اختر المادة</option>{products.map(x=><option value={x.id} key={x.id}>{x.name} — متوفر {x.qty}</option>)}</select><input name="qty" type="number" step=".01" min=".01" placeholder="الكمية" required/><input name="price" type="number" step=".01" placeholder="السعر" required/><select name="currency"><option>USD</option><option>IQD</option></select><select name="mode"><option value="cash">نقدي</option><option value="credit">آجل</option></select><button>حفظ العملية</button></form>}
function List({rows}){return <div className="list">{rows.length?rows.map((r,i)=><div className="row" key={i}><b>{r[0]}</b><span>{r[1]}</span></div>):<div className="empty">لا توجد بيانات بعد</div>}</div>}
function CashBox({tx,balance,onAdd}){const [kind,setKind]=useState('cash_income'),[amount,setAmount]=useState(''),[note,setNote]=useState('');const cashRows=tx.filter(t=>t.cash).slice().reverse();const save=e=>{e.preventDefault();if(!amount||+amount<=0)return alert('اكتب المبلغ');onAdd(kind,amount,note);setAmount('');setNote('')};const label=t=>({sale:'بيع نقدي',system:'بيع منظومة',purchase:'شراء نقدي',customer_payment:'تسديد عميل',system_payment:'تسديد منظومة',supplier_payment:'تسديد مورد',cash_income:'إيداع بالصندوق',cash_expense:'مصروف من الصندوق'}[t.kind]||t.kind);const isOut=t=>t.kind==='purchase'||t.kind==='supplier_payment'||t.kind==='cash_expense';return <div className="cashBox"><div className="cashHero"><small>رصيد الصندوق الحالي</small><b>{Number(balance||0).toLocaleString()} د.ع</b></div><form className="card form" onSubmit={save}><h3>حركة صندوق جديدة</h3><select value={kind} onChange={e=>setKind(e.target.value)}><option value="cash_income">إيداع / إدخال مبلغ</option><option value="cash_expense">مصروف / إخراج مبلغ</option></select><input type="number" value={amount} onChange={e=>setAmount(e.target.value)} placeholder="المبلغ بالدينار"/><input value={note} onChange={e=>setNote(e.target.value)} placeholder="البيان أو الملاحظات"/><button>حفظ حركة الصندوق</button></form><div className="cashLedger"><h3>حركات الصندوق</h3>{cashRows.length===0?<div className="empty">لا توجد حركات صندوق بعد</div>:cashRows.map(t=><div className="cashRow" key={t.id}><div><b>{label(t)}</b><small>{new Date(t.date).toLocaleDateString('ar-IQ')} {t.party?'• '+t.party:''}</small>{t.notes&&<small>{t.notes}</small>}</div><strong className={isOut(t)?'cashOut':'cashIn'}>{isOut(t)?'−':'+'} {Number(t.total||0).toLocaleString()} د.ع</strong></div>)}</div></div>}

function Profit({tx}){const p=tx.filter(t=>t.kind==='sale'||t.kind==='system');const usd=p.filter(t=>t.currency==='USD').reduce((s,t)=>s+t.total-(t.cost*t.qty),0);return <div className="cards"><div className="card"><small>ربح مبيعات الدولار</small><b>${usd.toFixed(2)}</b></div><div className="card"><small>ملاحظة</small><b className="smallb">ربح الدينار يحتاج سعر صرف العملية</b></div></div>}

function InvoiceBuilder({kind,products,parties,items,setItems,search,setSearch,onSave,history,onDeleteInvoice,onUpdateInvoice}){
 const [meta,setMeta]=useState({party:'',currency:'IQD',mode:kind==='purchase'?'credit':'cash',notes:'',expenses:''});
 const matches=search?products.filter(p=>(p.name+' '+p.code+' '+(p.brand||'')+' '+(p.category||'')).toLowerCase().includes(search.toLowerCase())).slice(0,12):[];
 const add=p=>{if(!items.some(x=>x.id===p.id))setItems([...items,{...p,qty:'',price:''}]);setSearch('')};
 const edit=(id,k,v)=>setItems(items.map(x=>x.id===id?{...x,[k]:+v}:x));
 const subtotal=items.reduce((a,x)=>a+(+x.qty||0)*(+x.price||0),0), expenses=(+meta.expenses||0), total=subtotal+expenses; const landed=(x)=>{const line=(+x.qty||0)*(+x.price||0);const allocated=subtotal>0?expenses*(line/subtotal):0;return (+x.qty||0)>0?((line+allocated)/(+x.qty||0)):0};
 const receiptHtml=(priced=true)=>{const rows=items.map(i=>'<tr><td>'+i.name+'<br><small>'+(i.brand||'')+' '+(i.category||'')+'</small></td><td>'+i.qty+'</td>'+(priced?'<td>'+Number(i.price||0).toLocaleString()+'</td><td>'+((+i.qty||0)*(+i.price||0)).toLocaleString()+'</td>':'')+'</tr>').join('');const headers='<th>المادة</th><th>العدد</th>'+(priced?'<th>السعر د.ع</th><th>المجموع د.ع</th>':'');const body='<div class="meta"><div><b>'+(kind==='purchase'?'المورد':'العميل')+':</b> '+(meta.party||'نقدي')+'</div><div><b>طريقة الدفع:</b> '+(meta.mode==='cash'?'نقدي':'آجل')+'</div></div><table><thead><tr>'+headers+'</tr></thead><tbody>'+rows+'</tbody></table>'+(expenses?'<div class="notes"><b>المصاريف الإضافية:</b> '+expenses.toLocaleString()+' د.ع</div>':'')+(meta.notes?'<div class="notes"><b>ملاحظات:</b> '+meta.notes+'</div>':'');return a4(kind==='purchase'?'فاتورة شراء':(priced?'فاتورة بيع - نسخة العميل':'فاتورة بيع - نسخة مخزنية'),body,(kind==='sale'&&!priced)?'':total.toLocaleString()+' د.ع',new Date().toLocaleDateString('ar-IQ'))}; const preview=()=>openA4(receiptHtml(true));
 const share=async()=>{const text='فاتورة '+(kind==='purchase'?'شراء':'بيع')+' - عبدالرحمن سولار\n'+items.map(i=>i.name+' × '+i.qty+' = '+((+i.qty||0)*(+i.price||0)).toLocaleString()+' د.ع').join('\n')+'\nالإجمالي: '+total.toLocaleString()+' د.ع';await shareA4(kind==='purchase'?'فاتورة-شراء':'فاتورة-بيع',text,receiptHtml())};
 return <div className="invoice"><div className="invoiceHead"><select value={meta.party} onChange={e=>setMeta({...meta,party:e.target.value})}><option value="">{kind==='purchase'?'اختر المورد':'اختر العميل / بيع نقدي'}</option>{parties.map(i=><option key={i.id}>{i.name}</option>)}</select><div className="fixedCurrency">الدينار العراقي (IQD)</div><select value={meta.mode} onChange={e=>setMeta({...meta,mode:e.target.value})}><option value="cash">نقدي</option><option value="credit">آجل</option></select></div><div className="searchBox"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="🔎 ابحث بالاسم أو الكود أو البراند أو الصنف..."/>{matches.length>0&&<div className="matches">{matches.map(i=><button key={i.id} onClick={()=>add(i)}><b>{i.name}</b><small>{i.brand||"بدون براند"} • {i.category||"بدون صنف"}{kind==="sale"?" • متوفر "+(i.qty||0):""}</small></button>)}</div>}</div><div className="invoiceLines">{items.map(i=><div className="invoiceLine" key={i.id}><div className="lineName"><div><b>{i.name}</b><small>{i.brand||"بدون براند"} • {i.category||"بدون صنف"}</small></div><button onClick={()=>setItems(items.filter(j=>j.id!==i.id))}>× حذف</button></div>{kind==="purchase"?<div className="costHint">السعر الواصل للمخزن: <b>{landed(i)?landed(i).toLocaleString(undefined,{maximumFractionDigits:2}):""} د.ع</b></div>:<div className="costHint saleCost">كلفة الشراء الواصلة: <b>{i.cost?fmt(i.cost)+" د.ع":"غير محددة"}</b></div>}<label>العدد<input inputMode="decimal" value={i.qty} onChange={e=>edit(i.id,"qty",e.target.value.replace(/,/g,""))} onBlur={e=>{if(e.target.value!=="")e.target.value=fmt(e.target.value)}} onFocus={e=>e.target.value=String(i.qty??"")}/></label><label>{kind==="purchase"?"سعر الشراء للوحدة":"سعر البيع"}<input inputMode="numeric" value={i.price===""?"":fmt(i.price)} onChange={e=>edit(i.id,"price",e.target.value.replace(/,/g,""))}/></label><div className="lineTotal"><span>المجموع</span><b>{((+i.qty||0)*(+i.price||0))?fmt((+i.qty||0)*(+i.price||0)):""}</b>{kind==="purchase"&&expenses>0&&(+i.qty||0)>0&&<small>واصل المخزن للوحدة: {landed(i).toLocaleString(undefined,{maximumFractionDigits:2})} د.ع</small>}{kind==="sale"&&(+i.price||0)>0&&(+i.cost||0)>0&&<small>الربح المتوقع: {fmt(((+i.price||0)-(+i.cost||0))*(+i.qty||0))} د.ع</small>}</div></div>)}</div><input inputMode="numeric" value={meta.expenses===""?"":fmt(meta.expenses)} onChange={e=>setMeta({...meta,expenses:e.target.value.replace(/,/g,"")})} placeholder="المصاريف الإضافية"/><textarea placeholder="ملاحظات الفاتورة" value={meta.notes} onChange={e=>setMeta({...meta,notes:e.target.value})}/><div className="grandTotal"><span>الإجمالي</span><b>{total.toLocaleString()} {meta.currency}</b></div><div className="invoiceActions"><button onClick={preview}>معاينة A4</button><button onClick={share}>مشاركة</button><button onClick={()=>saveA4(receiptHtml(true),kind==="purchase"?"فاتورة-شراء":"فاتورة-بيع-عميل")}>حفظ بالجهاز</button>{kind==="sale"&&<><button onClick={()=>openA4(receiptHtml(false))}>نسخة مخزنية بدون سعر</button><button onClick={()=>saveA4(receiptHtml(false),"فاتورة-بيع-مخزنية")}>حفظ نسخة المخزن</button><button onClick={()=>shareA4("فاتورة-بيع-مخزنية",items.map(i=>i.name+" × "+i.qty).join("\n"),receiptHtml(false))}>مشاركة للمخزن</button></>}<button className="danger" onClick={()=>{if(confirm('حذف الوصل الحالي؟'))setItems([])}}>حذف الوصل</button><button className="saveInvoice" onClick={()=>onSave(meta)}>حفظ الوصل</button></div><InvoiceHistory kind={kind} history={history} products={products} parties={parties} onDelete={onDeleteInvoice} onUpdate={onUpdateInvoice}/></div>
}
function InvoiceHistory({kind,history,products,parties,onDelete,onUpdate}){
 const [editing,setEditing]=useState(null),[draft,setDraft]=useState(null);
 const begin=t=>{setEditing(t.id);setDraft({...t,items:(t.items||[]).map(x=>({...x})),expenses:t.expenses||'',notes:t.notes||''})};
 const changeItem=(id,k,v)=>setDraft({...draft,items:draft.items.map(x=>x.id===id?{...x,[k]:v===''?'':+v}:x)});
 const saveEdit=()=>{const subtotal=draft.items.reduce((a,x)=>a+(+x.qty||0)*(+x.price||0),0);onUpdate(history.find(x=>x.id===editing),{...draft,subtotal,total:subtotal+(+draft.expenses||0)});setEditing(null);setDraft(null)};
 const savedDoc=(t,priced=true)=>{const rows=(t.items||[]).map(x=>'<tr><td>'+x.name+'<br><small>'+(x.brand||'')+' '+(x.category||'')+'</small></td><td>'+fmt(x.qty)+'</td>'+(priced?'<td>'+fmt(x.price)+'</td><td>'+fmt((+x.qty||0)*(+x.price||0))+'</td>':'')+'</tr>').join('');const heads='<th>المادة</th><th>العدد</th>'+(priced?'<th>السعر د.ع</th><th>المجموع د.ع</th>':'');const body='<div class="meta"><div><b>'+(kind==='purchase'?'المورد':'العميل')+':</b> '+(t.party||'نقدي')+'</div><div><b>التاريخ:</b> '+new Date(t.date).toLocaleDateString('ar-IQ')+'</div></div><table><thead><tr>'+heads+'</tr></thead><tbody>'+rows+'</tbody></table>'+(t.expenses?'<div class="notes"><b>المصاريف:</b> '+fmt(t.expenses)+' د.ع</div>':'')+(t.notes?'<div class="notes"><b>ملاحظات:</b> '+t.notes+'</div>':'');return a4(kind==='purchase'?'فاتورة شراء سابقة':(priced?'فاتورة بيع سابقة':'نسخة مخزنية - بيع سابق'),body,(kind==='sale'&&!priced)?'':fmt(t.total)+' د.ع',new Date(t.date).toLocaleDateString('ar-IQ'))};

 return <div className="history"><h3>الفواتير السابقة</h3>{history.length===0?<div className="empty">لا توجد فواتير محفوظة</div>:history.slice().reverse().map((t,i)=><div className="historyItem" key={t.id}>{editing===t.id?<div className="editInvoice"><b>تعديل فاتورة {kind==='sale'?'بيع':'شراء'} #{String(history.length-i).padStart(4,'0')}</b><select value={draft.party||''} onChange={e=>setDraft({...draft,party:e.target.value})}><option value="">نقدي / بدون اسم</option>{parties.map(p=><option key={p.id}>{p.name}</option>)}</select>{draft.items.map(x=><div className="editInvoiceLine" key={x.id}><b>{x.name}</b><label>العدد<input inputMode="decimal" value={x.qty} onChange={e=>changeItem(x.id,"qty",e.target.value.replace(/,/g,""))}/></label><label>السعر<input inputMode="numeric" value={x.price===""?"":fmt(x.price)} onChange={e=>changeItem(x.id,"price",e.target.value.replace(/,/g,""))}/></label><button className="dangerMini" onClick={()=>setDraft({...draft,items:draft.items.filter(y=>y.id!==x.id)})}>حذف المادة</button></div>)}<select value="" onChange={e=>{const p=products.find(x=>String(x.id)===e.target.value);if(p&&!draft.items.some(x=>x.id===p.id))setDraft({...draft,items:[...draft.items,{...p,qty:1,price:kind==='purchase'?p.cost:p.saleIqd}]})}}><option value="">+ إضافة مادة</option>{products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><input type="number" step=".01" placeholder="المصاريف الإضافية" value={draft.expenses} onChange={e=>setDraft({...draft,expenses:e.target.value})}/><textarea placeholder="ملاحظات" value={draft.notes||''} onChange={e=>setDraft({...draft,notes:e.target.value})}/><div className="editActions"><button onClick={saveEdit}>حفظ التعديل</button><button className="secondary" onClick={()=>{setEditing(null);setDraft(null)}}>إلغاء</button></div></div>:<><details><summary><b>{kind==='sale'?'بيع':'شراء'} #{String(history.length-i).padStart(4,'0')}</b><span>{new Date(t.date).toLocaleDateString('ar-IQ')}</span><strong>{Number(t.total||0).toLocaleString()} {t.currency}</strong></summary><div className="historyBody"><div>{t.party||'نقدي'}</div>{(t.items||[]).map((x,k)=><div className="historyLine" key={k}><span>{x.name}<small className="historyMeta">{x.brand||""}{x.brand&&x.category?" • ":""}{x.category||""}</small></span><span>{fmt(x.qty)} × {fmt(x.price)}</span><b>{fmt((+x.qty||0)*(+x.price||0))}</b></div>)}</div></details><div className="savedInvoiceActions"><button onClick={()=>openA4(savedDoc(t,true))}>معاينة</button><button onClick={()=>shareA4(kind==="purchase"?"فاتورة-شراء-سابقة":"فاتورة-بيع-سابقة",(kind==="purchase"?"فاتورة شراء":"فاتورة بيع")+" - "+(t.party||"")+"\nالإجمالي: "+fmt(t.total)+" د.ع",savedDoc(t,true))}>مشاركة</button>{kind==="sale"&&<button onClick={()=>openA4(savedDoc(t,false))}>نسخة مخزنية</button>}<button onClick={()=>begin(t)}>✏️ تعديل</button><button className="dangerMini" onClick={()=>onDelete(t)}>🗑️ حذف</button></div></>}</div>)}</div>
}
function ProductsManager({products,setProducts,addProduct,brands}){const [edit,setEdit]=useState(null);const categories=['انفيرتر','انفيرتر زراعي','All in One','بطارية','ألواح','مستلزمات','أخرى'];const saveEdit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);setProducts(products.map(p=>p.id===edit.id?{...p,name:f.get('name'),brand:f.get('brand')||'',category:f.get('category')||''}:p));setEdit(null)};const next=products.reduce((m,p)=>Math.max(m,parseInt(String(p.code||'').replace(/\D/g,''))||0),0)+1;return <><form onSubmit={addProduct} className="card form"><div className="autoCode"><span>كود المادة</span><b>{String(next).padStart(4,'0')}</b><small>يُنشأ تلقائياً</small></div><input name="name" placeholder="اسم المادة" required/><select name="brand" defaultValue="" required><option value="" disabled>اختر البراند</option>{brands.map(b=><option key={b.id} value={b.name}>{b.name}</option>)}</select><select name="category" defaultValue="" required><option value="" disabled>اختر الصنف</option>{categories.map(c=><option key={c}>{c}</option>)}</select><button>حفظ المادة</button></form>{edit&&<form onSubmit={saveEdit} className="card form"><div className="autoCode"><span>كود المادة</span><b>{edit.code}</b></div><input name="name" defaultValue={edit.name} placeholder="اسم المادة" required/><select name="brand" defaultValue={edit.brand||''} required><option value="" disabled>اختر البراند</option>{brands.map(b=><option key={b.id} value={b.name}>{b.name}</option>)}</select><select name="category" defaultValue={edit.category||''} required><option value="" disabled>اختر الصنف</option>{categories.map(c=><option key={c}>{c}</option>)}</select><button>حفظ التعديل</button></form>}<div className="list">{products.map(p=><div className="row manageRow" key={p.id}><div><b>{p.name}</b><span>كود: {p.code}{p.brand?' • '+p.brand:''}{p.category?' • '+p.category:''}</span></div><div className="rowActions"><button onClick={()=>setEdit(p)}>تعديل</button><button className="dangerMini" onClick={()=>confirm('حذف المادة؟')&&setProducts(products.filter(x=>x.id!==p.id))}>حذف</button></div></div>)}</div></>}
function BrandsManager({brands,setBrands}){const [edit,setEdit]=useState(null);const add=e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get('name')||'').trim();if(!name)return;if(brands.some(b=>b.name.toLowerCase()===name.toLowerCase()))return alert('البراند موجود مسبقاً');setBrands([...brands,{id:Date.now(),name}]);e.currentTarget.reset()};const saveEdit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get('name')||'').trim();if(!name)return;setBrands(brands.map(b=>b.id===edit.id?{...b,name}:b));setEdit(null)};return <><form onSubmit={add} className="card form"><input name="name" placeholder="اسم البراند" required/><button>إضافة البراند</button></form>{edit&&<form onSubmit={saveEdit} className="card form"><b>تعديل البراند</b><input name="name" defaultValue={edit.name} required/><button>حفظ التعديل</button></form>}<div className="list">{brands.length===0?<div className="empty">لا توجد براندات بعد</div>:brands.map(b=><div className="row manageRow" key={b.id}><b>{b.name}</b><div className="rowActions"><button onClick={()=>setEdit(b)}>تعديل</button><button className="dangerMini" onClick={()=>confirm('حذف البراند من القائمة؟')&&setBrands(brands.filter(x=>x.id!==b.id))}>حذف</button></div></div>)}</div></>}

function PartyManager({customer=false,rows,setRows,tx,onAdd,onPayment}){const [open,setOpen]=useState(null),[edit,setEdit]=useState(null);const relevant=r=>tx.filter(t=>t.party===r.name&&(customer?(t.kind==='sale'||t.kind==='system'||t.kind==='customer_payment'||t.kind==='system_payment'):(t.kind==='purchase'||t.kind==='supplier_payment')));const isPay=t=>t.kind==='customer_payment'||t.kind==='supplier_payment'||t.kind==='system_payment';const balance=r=>relevant(r).reduce((a,t)=>a+(isPay(t)?-Number(t.total||0):Number(t.total||0)),0);const editSave=e=>{e.preventDefault();const f=new FormData(e.currentTarget);setRows(rows.map(r=>r.id===edit.id?{...r,name:f.get('name'),phone:f.get('phone')||'',customerType:f.get('customerType')||''}:r));setEdit(null)};return <><form onSubmit={onAdd} className="card form"><input name="name" placeholder={customer?'اسم الزبون':'اسم المورد'} required/><input name="phone" placeholder="رقم الهاتف"/>{customer&&<select name="customerType" defaultValue=""><option value="">نوع الزبون</option><option value="مفرد - منظومات">مفرد - منظومات</option><option value="جملة - بيع جملة">جملة - بيع جملة</option></select>}<button>إضافة {customer?'عميل':'مورد'}</button></form>{edit&&<form onSubmit={editSave} className="card form"><input name="name" defaultValue={edit.name}/><input name="phone" defaultValue={edit.phone}/>{customer&&<select name="customerType" defaultValue={edit.customerType||''}><option value="">نوع الزبون</option><option value="مفرد - منظومات">مفرد - منظومات</option><option value="جملة - بيع جملة">جملة - بيع جملة</option></select>}<button>حفظ التعديل</button></form>}<div className="list">{rows.map(r=><div className="partyCard" key={r.id}><div className="partyTop"><div><b>{r.name}</b><span>{customer?r.customerType||'':''}</span></div><strong>الرصيد: {balance(r).toLocaleString()}</strong></div><div className="partyActions"><button onClick={()=>setOpen(open===r.id?null:r.id)}>{customer?'الحساب والفواتير':'الحساب والفواتير'}</button>{!customer&&<button onClick={()=>{const a=prompt('مبلغ التسديد');if(a){const note=prompt('ملاحظات التسديد')||'';onPayment(r,a,note)}}}>تسديد</button>}<button onClick={()=>setEdit(r)}>تعديل</button><button className="dangerMini" onClick={()=>confirm('حذف من القائمة؟ الحركات القديمة تبقى محفوظة.')&&setRows(rows.filter(x=>x.id!==r.id))}>حذف</button></div>{open===r.id&&<div className="accountBox">{relevant(r).slice().reverse().map(t=><div className="accountLine" key={t.id}><span>{new Date(t.date).toLocaleDateString('ar-IQ')}</span><span>{isPay(t)?'تسديد':'فاتورة'}</span><b>{Number(t.total||0).toLocaleString()} {t.currency}</b></div>)}</div>}</div>)}</div></>}

function CustomerDebts({customers,tx}){const [type,setType]=useState('all');const debt=c=>tx.filter(t=>t.party===c.name&&(t.kind==='sale'||t.kind==='system'||t.kind==='customer_payment'||t.kind==='system_payment')).reduce((a,t)=>a+((t.kind==='customer_payment'||t.kind==='system_payment')?-Number(t.total||0):Number(t.total||0)),0);const rows=customers.map(c=>({...c,debt:debt(c)})).filter(c=>c.debt>0).filter(c=>type==='all'||(type==='retail'?String(c.customerType||'').includes('مفرد'):String(c.customerType||'').includes('جملة')));const total=rows.reduce((a,c)=>a+c.debt,0);const title=type==='retail'?'مدينو المنظومات':type==='wholesale'?'مدينو الجملة':'جميع مديني العملاء';const html=()=>{const trs=rows.map((c,i)=>'<tr><td>'+(i+1)+'</td><td>'+c.name+'</td><td>'+(c.customerType||'')+'</td><td>'+fmt(c.debt)+' د.ع</td></tr>').join('');return a4(title,'<table><thead><tr><th>#</th><th>العميل</th><th>النوع</th><th>الدين</th></tr></thead><tbody>'+trs+'</tbody></table>',fmt(total)+' د.ع',new Date().toLocaleDateString('ar-IQ'))};const text=()=>title+'\n'+rows.map(c=>c.name+' | '+(c.customerType||'')+' | '+fmt(c.debt)+' د.ع').join('\n')+'\nالإجمالي: '+fmt(total)+' د.ع';return <section className="debtSection"><div className="debtHead"><h3>مدينو العملاء</h3><b>{fmt(total)} د.ع</b></div><div className="statementTabs"><button className={type==='all'?'active':''} onClick={()=>setType('all')}>الكل</button><button className={type==='wholesale'?'active':''} onClick={()=>setType('wholesale')}>الجملة</button><button className={type==='retail'?'active':''} onClick={()=>setType('retail')}>المنظومات</button></div><div className="debtList">{rows.length?rows.map(c=><div className="debtRow" key={c.id}><div><b>{c.name}</b><small>{c.customerType||''}</small></div><strong>{fmt(c.debt)} د.ع</strong></div>):<div className="empty">لا يوجد عملاء مدينون ضمن هذا التصنيف</div>}</div><div className="receiptCopies"><button onClick={()=>openA4(html())}>معاينة A4</button><button onClick={()=>saveA4(html(),title)}>PDF / حفظ</button><button onClick={()=>shareA4(title,text(),html())}>مشاركة</button></div></section>}

function SystemPayment({customers,tx,onSave}){const eligible=customers.filter(c=>String(c.customerType||'').includes('مفرد'));const [party,setParty]=useState(''),[invoiceId,setInvoiceId]=useState(''),[amount,setAmount]=useState(''),[notes,setNotes]=useState(''),[last,setLast]=useState(null);const systems=tx.filter(t=>t.kind==='system'&&(!party||t.party===party));const selected=systems.find(t=>String(t.id)===String(invoiceId));const paid=selected?tx.filter(t=>t.kind==='system_payment'&&String(t.systemInvoiceId)===String(selected.id)).reduce((a,t)=>a+Number(t.total||0),0):0;const oldBalance=selected?Math.max(0,Number(selected.total||0)-paid):0;const remaining=oldBalance-(+amount||0);const receipt=(r=last||{party,amount:+amount||0,oldBalance,remaining,notes,date:new Date().toISOString(),systemInvoiceId:invoiceId,invoiceTotal:selected?.total||0})=>{const inv=tx.find(t=>String(t.id)===String(r.systemInvoiceId));const materials=(inv?.items||[]).map(i=>'<tr><td>'+i.name+'<br><small>'+(i.brand||'')+' • '+(i.category||'')+'</small></td><td>'+fmt(i.qty)+'</td></tr>').join('');const body='<div class="meta"><div><b>العميل:</b> '+r.party+'</div><div><b>التاريخ:</b> '+new Date(r.date).toLocaleDateString('ar-IQ')+'</div><div><b>قيمة المنظومة:</b> '+fmt(r.invoiceTotal)+' د.ع</div><div><b>رقم العملية:</b> '+r.systemInvoiceId+'</div></div>'+(materials?'<table><thead><tr><th>مواد المنظومة</th><th>العدد</th></tr></thead><tbody>'+materials+'</tbody></table>':'')+'<table><thead><tr><th>الحساب السابق</th><th>المبلغ المسدد</th><th>المتبقي</th></tr></thead><tbody><tr><td>'+fmt(r.oldBalance)+' د.ع</td><td>'+fmt(r.amount)+' د.ع</td><td>'+fmt(r.remaining)+' د.ع</td></tr></tbody></table>'+(r.notes?'<div class="notes"><b>ملاحظات:</b> '+r.notes+'</div>':'');return a4('وصل تسديد منظومة',body,fmt(r.remaining)+' د.ع',r.party)};const save=e=>{e.preventDefault();if(!party)return alert('اختر العميل');if(!selected)return alert('اختر المنظومة');if(!amount||+amount<=0)return alert('اكتب مبلغ التسديد');if(+amount>oldBalance)return alert('المبلغ أكبر من المتبقي على المنظومة');const row={id:Date.now(),kind:'system_payment',systemInvoiceId:selected.id,party,total:+amount,currency:'IQD',cash:true,notes,oldBalance,remaining,invoiceTotal:Number(selected.total||0),date:new Date().toISOString()};onSave(row);setLast({...row,amount:+amount});setAmount('');setNotes('');alert('تم حفظ تسديد المنظومة')};const share=async()=>{if(!last)return;const text='وصل تسديد منظومة - '+last.party+'\nقيمة المنظومة: '+fmt(last.invoiceTotal)+' د.ع\nالحساب السابق: '+fmt(last.oldBalance)+' د.ع\nالمبلغ المسدد: '+fmt(last.amount)+' د.ع\nالمتبقي: '+fmt(last.remaining)+' د.ع'+(last.notes?'\nملاحظات: '+last.notes:'');await shareA4('وصل-تسديد-منظومة-'+last.party,text,receipt(last))};return <div className="paymentPage"><form className="card form" onSubmit={save}><select value={party} onChange={e=>{setParty(e.target.value);setInvoiceId('');setLast(null)}}><option value="">اختر مشتري المنظومة</option>{eligible.map(c=><option key={c.id}>{c.name}</option>)}</select><select value={invoiceId} onChange={e=>{setInvoiceId(e.target.value);setLast(null)}} disabled={!party}><option value="">اختر المنظومة المباعة</option>{systems.map(t=><option key={t.id} value={t.id}>{new Date(t.date).toLocaleDateString('ar-IQ')} — {fmt(t.total)} د.ع</option>)}</select>{selected&&<div className="systemPaymentDetails"><div><span>قيمة المنظومة</span><b>{fmt(selected.total)} د.ع</b></div><div><span>المسدد سابقاً</span><b>{fmt(paid)} د.ع</b></div><div><span>المتبقي الحالي</span><b>{fmt(oldBalance)} د.ع</b></div><div className="systemMaterials"><span>المواد</span>{(selected.items||[]).map(i=><small key={i.id}>{i.name} — {i.brand||''} {i.category||''} × {fmt(i.qty)}</small>)}</div></div>}<input inputMode="numeric" value={amount===''?'':fmt(amount)} onChange={e=>setAmount(e.target.value.replace(/,/g,''))} placeholder="المبلغ المسدد"/><textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder="ملاحظات التسديد"/>{selected&&amount&&<div className="paymentCalc"><div><span>الحساب السابق</span><b>{fmt(oldBalance)} د.ع</b></div><div><span>المبلغ المسدد</span><b>{fmt(amount)} د.ع</b></div><div><span>المتبقي</span><b>{fmt(remaining)} د.ع</b></div></div>}<div className="receiptCopies paymentActions"><button type="button" onClick={()=>openA4(receipt())} disabled={!party||!invoiceId||!amount}>معاينة الوصل</button><button type="button" onClick={()=>saveA4(receipt(),'وصل-تسديد-منظومة-'+party)} disabled={!party||!invoiceId||!amount}>حفظ / PDF</button><button type="button" onClick={()=>shareA4('وصل-تسديد-منظومة-'+party,'وصل تسديد منظومة - '+party+'\nالحساب السابق: '+fmt(oldBalance)+' د.ع\nالمبلغ المسدد: '+fmt(amount)+' د.ع\nالمتبقي: '+fmt(remaining)+' د.ع',receipt())} disabled={!party||!invoiceId||!amount}>مشاركة</button></div><button>حفظ تسديد المنظومة</button></form>{last&&<div className="receiptPanel"><h3>وصل تسديد المنظومة</h3><div className="paymentCalc"><div><span>قيمة المنظومة</span><b>{fmt(last.invoiceTotal)} د.ع</b></div><div><span>الحساب السابق</span><b>{fmt(last.oldBalance)} د.ع</b></div><div><span>المبلغ المسدد</span><b>{fmt(last.amount)} د.ع</b></div><div><span>المتبقي</span><b>{fmt(last.remaining)} د.ع</b></div></div><div className="receiptCopies"><button onClick={()=>openA4(receipt(last))}>معاينة A4</button><button onClick={()=>saveA4(receipt(last),'وصل-تسديد-منظومة-'+last.party)}>PDF / حفظ</button><button onClick={share}>مشاركة</button></div></div>}</div>}

function CustomerPayment({customers,tx,onSave}){const eligible=customers.filter(c=>String(c.customerType||'').includes('جملة'));const [party,setParty]=useState(''),[amount,setAmount]=useState(''),[notes,setNotes]=useState(''),[last,setLast]=useState(null);const movements=tx.filter(t=>t.party===party&&(t.kind==='sale'||t.kind==='system'||t.kind==='customer_payment'));const oldBalance=movements.reduce((a,t)=>a+(t.kind==='customer_payment'?-Number(t.total||0):Number(t.total||0)),0);const remaining=oldBalance-(+amount||0);const receipt=(r=last||{party,amount:+amount||0,oldBalance,remaining,notes,date:new Date().toISOString()})=>{const body='<div class="meta"><div><b>العميل:</b> '+r.party+'</div><div><b>التاريخ:</b> '+new Date(r.date).toLocaleDateString('ar-IQ')+'</div></div><table><thead><tr><th>الحساب السابق</th><th>المبلغ المسدد</th><th>المتبقي</th></tr></thead><tbody><tr><td>'+fmt(r.oldBalance)+' د.ع</td><td>'+fmt(r.amount)+' د.ع</td><td>'+fmt(r.remaining)+' د.ع</td></tr></tbody></table>'+(r.notes?'<div class="notes"><b>ملاحظات:</b> '+r.notes+'</div>':'');return a4('وصل تسديد عميل',body,fmt(r.remaining)+' د.ع',r.party)};const save=e=>{e.preventDefault();if(!party)return alert('اختر العميل');if(!amount||+amount<=0)return alert('اكتب مبلغ التسديد');const row={id:Date.now(),kind:'customer_payment',party,total:+amount,currency:'IQD',cash:true,notes,oldBalance,remaining,date:new Date().toISOString()};onSave(row);setLast({...row,amount:+amount});setAmount('');setNotes('');alert('تم حفظ تسديد العميل')};const share=async()=>{const r=last;if(!r)return alert('احفظ التسديد أولاً');const text='وصل تسديد عميل - '+r.party+'\nالحساب السابق: '+fmt(r.oldBalance)+' د.ع\nالمبلغ المسدد: '+fmt(r.amount)+' د.ع\nالمتبقي: '+fmt(r.remaining)+' د.ع'+(r.notes?'\nملاحظات: '+r.notes:'');await shareA4('وصل-تسديد-'+r.party,text,receipt(r))};return <div className="paymentPage"><form className="card form" onSubmit={save}><select value={party} onChange={e=>{setParty(e.target.value);setLast(null)}}><option value="">اختر عميل الجملة</option>{eligible.map(c=><option key={c.id}>{c.name}</option>)}</select>{party&&<div className="paymentBalance"><small>الحساب الحالي</small><b>{fmt(oldBalance)} د.ع</b></div>}<input inputMode="numeric" value={amount===''?'':fmt(amount)} onChange={e=>setAmount(e.target.value.replace(/,/g,''))} placeholder="المبلغ المسدد"/><textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder="ملاحظات التسديد"/>{party&&amount&&<div className="paymentCalc"><div><span>الحساب السابق</span><b>{fmt(oldBalance)} د.ع</b></div><div><span>المبلغ المسدد</span><b>{fmt(amount)} د.ع</b></div><div><span>المتبقي</span><b>{fmt(remaining)} د.ع</b></div></div>}<div className="receiptCopies paymentActions"><button type="button" onClick={()=>openA4(receipt())} disabled={!party||!amount}>معاينة الوصل</button><button type="button" onClick={()=>saveA4(receipt(),"وصل-تسديد-"+party)} disabled={!party||!amount}>حفظ / PDF</button><button type="button" onClick={()=>shareA4("وصل-تسديد-"+party,"وصل تسديد عميل - "+party+"\nالحساب السابق: "+fmt(oldBalance)+" د.ع\nالمبلغ المسدد: "+fmt(amount)+" د.ع\nالمتبقي: "+fmt(remaining)+" د.ع",receipt())} disabled={!party||!amount}>مشاركة</button></div><button>حفظ التسديد</button></form>{last&&<div className="receiptPanel"><h3>وصل التسديد</h3><div className="paymentCalc"><div><span>الحساب السابق</span><b>{fmt(last.oldBalance)} د.ع</b></div><div><span>المبلغ المسدد</span><b>{fmt(last.amount)} د.ع</b></div><div><span>المتبقي</span><b>{fmt(last.remaining)} د.ع</b></div></div><div className="receiptCopies"><button onClick={()=>openA4(receipt(last))}>معاينة A4</button><button onClick={()=>saveA4(receipt(last),'وصل-تسديد-'+last.party)}>PDF / حفظ</button><button onClick={share}>مشاركة</button></div></div>}</div>}

function StatementPage({customer=false,parties,tx}){const [party,setParty]=useState(''),[from,setFrom]=useState(''),[to,setTo]=useState(''),[view,setView]=useState('all');const base=tx.filter(t=>t.party===party&&(customer?(t.kind==='sale'||t.kind==='system'||t.kind==='customer_payment'):(t.kind==='purchase'||t.kind==='supplier_payment'))).filter(t=>(!from||t.date.slice(0,10)>=from)&&(!to||t.date.slice(0,10)<=to)).sort((a,b)=>new Date(a.date)-new Date(b.date));const isPay=t=>t.kind==='customer_payment'||t.kind==='supplier_payment';let running=0;const all=base.map(t=>{running+=isPay(t)?-Number(t.total||0):Number(t.total||0);return {...t,payment:isPay(t),balance:running}});const data=all.filter(t=>view==='all'||(view==='payments'?t.payment:!t.payment));const finalBalance=all.length?all[all.length-1].balance:0;const text=()=>data.map(t=>new Date(t.date).toLocaleDateString('ar-IQ')+' | '+(t.payment?'تسديد':'فاتورة')+' | '+Number(t.total||0).toLocaleString()+' د.ع'+(t.notes?' | '+t.notes:'')).join('\n');const statementHtml=()=>{const rows=data.map(t=>'<tr><td>'+new Date(t.date).toLocaleDateString('ar-IQ')+'</td><td>'+(t.payment?'تسديد':'فاتورة')+'</td><td>'+Number(t.total||0).toLocaleString()+'</td><td><b>'+Number(t.balance||0).toLocaleString()+'</b></td><td>'+(t.notes||'')+'</td></tr>').join('');const body='<div class="meta"><div><b>الحساب:</b> '+party+'</div><div><b>الفترة:</b> '+(from||'البداية')+' — '+(to||'اليوم')+'</div></div><table><thead><tr><th>التاريخ</th><th>البيان</th><th>المبلغ د.ع</th><th>الرصيد بعد الحركة</th><th>الملاحظات</th></tr></thead><tbody>'+rows+'</tbody></table>';return a4(customer?'كشف حساب عميل':'كشف حساب مورد',body,finalBalance.toLocaleString()+' د.ع',party)};const preview=()=>openA4(statementHtml());const share=async()=>{const x='كشف حساب '+party+'\n'+text()+'\nالرصيد النهائي: '+finalBalance.toLocaleString()+' د.ع';await shareA4('كشف-حساب-'+party,x,statementHtml())};return <div className="statement"><div className="card form"><select value={party} onChange={e=>setParty(e.target.value)}><option value="">{customer?'اختر الزبون':'اختر المورد'}</option>{parties.map(p=><option key={p.id}>{p.name}</option>)}</select><div className="dateRange"><label>من<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>إلى<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label></div><div className="statementTabs"><button type="button" className={view==='all'?'active':''} onClick={()=>setView('all')}>الكشف الرئيسي</button><button type="button" className={view==='invoices'?'active':''} onClick={()=>setView('invoices')}>{customer?'المبيعات':'المشتريات'}</button><button type="button" className={view==='payments'?'active':''} onClick={()=>setView('payments')}>التسديدات</button></div></div>{party&&<><div className="statementTable"><div className="statementRow running head"><b>التاريخ</b><b>البيان</b><b>المبلغ</b><b>الرصيد بعد الحركة</b><b>الملاحظات</b></div>{data.length?data.map(t=><div className="statementRow running" key={t.id}><span>{new Date(t.date).toLocaleDateString("ar-IQ")}</span><span>{t.payment?"تسديد":customer?(t.kind==="system"?"بيع منظومة":"مبيعات"):"مشتريات"}</span><b>{fmt(t.total)} د.ع</b><strong className="runningBalance">{fmt(t.balance)} د.ع</strong><span className="statementNote">{t.notes||""}</span></div>):<div className="empty">لا توجد حركات ضمن الفترة</div>}</div><div className="statementBalance"><span>الرصيد النهائي</span><b>{finalBalance.toLocaleString()} د.ع</b></div><div className="invoiceActions"><button onClick={preview}>معاينة A4</button><button onClick={share}>مشاركة</button><button className="saveInvoice" onClick={()=>saveA4(statementHtml(),"كشف-حساب-"+party)}>حفظ في الجهاز</button></div></>}</div>}
function SystemSale({products,customers,onSave}){const [items,setItems]=useState([]),[q,setQ]=useState(''),[party,setParty]=useState(''),[expenses,setExpenses]=useState(''),[salePrice,setSalePrice]=useState(''),[notes,setNotes]=useState('');const m=q?products.filter(p=>(p.name+' '+p.code+' '+(p.brand||'')+' '+(p.category||'')).toLowerCase().includes(q.toLowerCase())).slice(0,12):[];const cost=items.reduce((a,i)=>a+(+i.qty||0)*(+i.cost||0),0),profit=(+salePrice||0)-cost-(+expenses||0);const add=p=>{if(!items.some(i=>i.id===p.id))setItems([...items,{...p,qty:''}]);setQ('')};const doc=(customerCopy=true)=>{const rows=items.map(i=>'<tr><td>'+i.name+'<br><small>'+(i.brand||'')+' • '+(i.category||'')+'</small></td><td>'+i.qty+'</td>'+(customerCopy?'':'')+'</tr>').join('');const body='<div class="meta"><div><b>العميل:</b> '+(party||'نقدي')+'</div><div><b>نوع المستند:</b> '+(customerCopy?'نسخة العميل':'نسخة مخزنية')+'</div></div><table><thead><tr><th>المادة</th><th>العدد</th></tr></thead><tbody>'+rows+'</tbody></table>'+(notes?'<div class="notes"><b>ملاحظات:</b> '+notes+'</div>':'')+(customerCopy?'<div class="notes"><b>سعر المنظومة:</b> '+Number(salePrice||0).toLocaleString()+' د.ع</div>':'');return a4(customerCopy?'وصل بيع منظومة':'وصل مخزني - منظومة',body,customerCopy?Number(salePrice||0).toLocaleString()+' د.ع':'',new Date().toLocaleDateString('ar-IQ'))};const share=async(customerCopy)=>shareA4(customerCopy?'وصل-منظومة-للعميل':'وصل-منظومة-مخزني',(customerCopy?'وصل العميل':'وصل مخزني')+' - '+(party||'')+'\n'+items.map(i=>i.name+' × '+i.qty).join('\n')+(customerCopy?'\nالسعر: '+Number(salePrice||0).toLocaleString()+' د.ع':''),doc(customerCopy));return <div className="invoice"><select value={party} onChange={e=>setParty(e.target.value)}><option value="">اختر العميل</option>{customers.map(i=><option key={i.id}>{i.name}</option>)}</select><div className="searchBox"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="🔎 ابحث بالاسم أو البراند أو الصنف"/>{m.length>0&&<div className="matches">{m.map(i=><button key={i.id} onClick={()=>add(i)}><b>{i.name}</b><small>{i.brand||'بدون براند'} • {i.category||'بدون صنف'}</small></button>)}</div>}</div>{items.map(i=><div className="invoiceLine" key={i.id}><div className="lineName"><div><b>{i.name}</b><small>{i.brand||''} • {i.category||''}</small></div><button onClick={()=>setItems(items.filter(j=>j.id!==i.id))}>×</button></div><label>العدد<input type="number" value={i.qty} onChange={e=>setItems(items.map(j=>j.id===i.id?{...j,qty:e.target.value}:j))}/></label><div className="lineTotal">كلفة المادة <b>{((+i.qty||0)*(+i.cost||0)).toLocaleString()} د.ع</b></div></div>)}<input type="number" step=".01" placeholder="المصاريف الإضافية" value={expenses} onChange={e=>setExpenses(e.target.value)}/><input type="number" step=".01" placeholder="سعر بيع المنظومة بالدينار" value={salePrice} onChange={e=>setSalePrice(e.target.value)}/><textarea placeholder="ملاحظات الوصل" value={notes} onChange={e=>setNotes(e.target.value)}/><div className="systemTotals"><div>كلفة المواد <b>{cost?cost.toLocaleString():''}</b></div><div>المصاريف <b>{expenses?Number(expenses).toLocaleString():''}</b></div><div>الكلفة الكلية <b>{cost||expenses?(cost+(+expenses||0)).toLocaleString():''}</b></div><div className={profit>=0?'profitGood':'profitBad'}>الربح الصافي <b>{salePrice?profit.toLocaleString()+' د.ع':''}</b></div></div><div className="receiptCopies"><button onClick={()=>openA4(doc(true))}>معاينة وصل العميل</button><button onClick={()=>openA4(doc(false))}>معاينة النسخة المخزنية</button><button onClick={()=>saveA4(doc(true),'وصل-منظومة-للعميل')}>PDF / حفظ العميل</button><button onClick={()=>saveA4(doc(false),'وصل-منظومة-مخزني')}>PDF / حفظ المخزن</button><button onClick={()=>share(true)}>مشاركة للعميل</button><button onClick={()=>share(false)}>مشاركة للمخزن</button></div><button className="primaryWide" onClick={()=>{if(!items.length)return alert('أضف مواد');if(!salePrice)return alert('اكتب سعر بيع المنظومة');onSave({items:items.map(i=>({...i,qty:+i.qty||0})),total:+salePrice,expenses:+expenses||0,cost,profit,currency:'IQD',party,notes,cash:true});setItems([]);setSalePrice('');setExpenses('');setNotes('');alert('تم حفظ بيع المنظومة')}}>حفظ بيع المنظومة</button></div>}
function StockReport({products}){const [cost,setCost]=useState(true);const available=products.filter(p=>(+p.qty||0)>0);const total=available.reduce((a,p)=>a+p.qty*p.cost,0);const makeText=()=>available.map(p=>p.name+' | '+p.qty+(cost?' | '+p.cost+' د.ع | '+fmt((+p.qty||0)*(+p.cost||0))+' د.ع':'')).join('\n')+(cost?'\nالمجموع الكلي: '+fmt(total)+' د.ع':'');const stockHtml=()=>{const rows=available.map(p=>'<tr><td>'+p.name+'<br><small>'+(p.brand||'')+' '+(p.category||'')+'</small></td><td>'+(p.qty||'')+'</td>'+(cost?'<td>'+Number(p.cost||0).toLocaleString()+'</td><td>'+((+p.qty||0)*(+p.cost||0)).toLocaleString()+'</td>':'')+'</tr>').join('');const body='<table><thead><tr><th>المادة</th><th>العدد</th>'+(cost?'<th>الكلفة د.ع</th><th>المجموع د.ع</th>':'')+'</tr></thead><tbody>'+rows+'</tbody></table>';return a4('كشف المخزون',body,cost?total.toLocaleString()+' د.ع':'',new Date().toLocaleDateString('ar-IQ'))}; const preview=()=>openA4(stockHtml());const share=async()=>{const text='مخزون عبدالرحمن سولار\n'+makeText();await shareA4('كشف-المخزون',text,stockHtml())};return <div><div className="reportOptions"><label><input type="checkbox" checked={cost} onChange={e=>setCost(e.target.checked)}/> مع الكلفة</label></div><div className="stockTable"><div className="stockRow head"><b>المادة</b><b>العدد</b>{cost&&<><b>السعر</b><b>المجموع</b></>}</div>{available.map(p=><div className="stockRow" key={p.id}><span className="stockMaterial"><b>{p.name}</b><small>{p.brand||"بدون براند"} • {p.category||"بدون صنف"}</small></span><span>{p.qty}</span>{cost&&<><span>{fmt(p.cost)} د.ع</span><span>{fmt((+p.qty||0)*(+p.cost||0))} د.ع</span></>}</div>)}</div>{cost&&<div className="grandTotal"><span>المجموع الكلي</span><b>{fmt(total)} د.ع</b></div>}<div className="invoiceActions"><button onClick={preview}>معاينة</button><button onClick={()=>saveA4(stockHtml(),'كشف-المخزون')}>حفظ في الجهاز</button><button className="saveInvoice" onClick={share}>مشاركة</button></div></div>}